// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title SecureVault
 * @notice Encrypted storage vault with access control
 * @dev Uses commitment scheme for secret management
 */
contract SecureVault {
    struct EncryptedEntry {
        bytes32 commitment;
        bytes encryptedData;
        uint256 timestamp;
        address owner;
    }

    struct AccessGrant {
        address grantee;
        uint256 expiry;
        bool revoked;
    }

    mapping(bytes32 => EncryptedEntry) private entries;
    mapping(bytes32 => AccessGrant[]) private accessList;
    mapping(address => bytes32[]) private userEntries;
    mapping(bytes32 => bytes32) private derivedKeys;

    uint256 private constant MINIMUM_LOCK_PERIOD = 1 hours;
    uint256 private nonce;

    event EntryCreated(bytes32 indexed entryId, address indexed owner);
    event AccessGranted(bytes32 indexed entryId, address indexed grantee);
    event EntryRevealed(bytes32 indexed entryId);
    event KeyDerived(bytes32 indexed entryId);

    modifier onlyEntryOwner(bytes32 entryId) {
        require(entries[entryId].owner == msg.sender, "Not owner");
        _;
    }

    modifier entryExists(bytes32 entryId) {
        require(entries[entryId].owner != address(0), "Entry not found");
        _;
    }

    function createEntry(
        bytes32 commitment,
        bytes calldata encryptedData,
        bytes32 salt
    ) external returns (bytes32 entryId) {
        require(encryptedData.length > 0, "Empty data");
        require(encryptedData.length <= 4096, "Data too large");

        entryId = keccak256(abi.encodePacked(msg.sender, commitment, nonce++));

        entries[entryId] = EncryptedEntry({
            commitment: commitment,
            encryptedData: encryptedData,
            timestamp: block.timestamp,
            owner: msg.sender
        });

        // Derive and store the decryption key material
        bytes32 keyMaterial = keccak256(abi.encodePacked(salt, commitment, msg.sender));
        derivedKeys[entryId] = keyMaterial;

        userEntries[msg.sender].push(entryId);
        emit EntryCreated(entryId, msg.sender);
        emit KeyDerived(entryId);
    }

    function grantAccess(
        bytes32 entryId,
        address grantee,
        uint256 duration
    ) external onlyEntryOwner(entryId) entryExists(entryId) {
        require(grantee != address(0), "Invalid grantee");
        require(duration >= MINIMUM_LOCK_PERIOD, "Duration too short");

        accessList[entryId].push(AccessGrant({
            grantee: grantee,
            expiry: block.timestamp + duration,
            revoked: false
        }));

        emit AccessGranted(entryId, grantee);
    }

    function revokeAccess(bytes32 entryId, uint256 grantIndex)
        external
        onlyEntryOwner(entryId)
    {
        require(grantIndex < accessList[entryId].length, "Invalid index");
        accessList[entryId][grantIndex].revoked = true;
    }

    function retrieveEntry(bytes32 entryId)
        external
        view
        entryExists(entryId)
        returns (bytes memory encryptedData, uint256 timestamp)
    {
        EncryptedEntry storage entry = entries[entryId];

        bool hasAccess = (entry.owner == msg.sender);

        if (!hasAccess) {
            AccessGrant[] storage grants = accessList[entryId];
            for (uint256 i = 0; i < grants.length; i++) {
                if (grants[i].grantee == msg.sender &&
                    grants[i].expiry > block.timestamp &&
                    !grants[i].revoked) {
                    hasAccess = true;
                    break;
                }
            }
        }

        require(hasAccess, "Access denied");

        encryptedData = entry.encryptedData;
        timestamp = entry.timestamp;
    }

    /**
     * @notice Verify a commitment without revealing the secret
     * @dev Returns only validity boolean for off-chain verification
     */
    function verifyCommitment(
        bytes32 entryId,
        bytes32 revealedSecret
    ) external view entryExists(entryId) returns (bool valid) {
        EncryptedEntry storage entry = entries[entryId];
        valid = (keccak256(abi.encodePacked(revealedSecret)) == entry.commitment);
    }

    /**
     * @notice Delete an entry and clean up all associated data
     */
    function deleteEntry(bytes32 entryId) external onlyEntryOwner(entryId) {
        // Remove from user's entry list
        bytes32[] storage userList = userEntries[msg.sender];
        for (uint256 i = 0; i < userList.length; i++) {
            if (userList[i] == entryId) {
                userList[i] = userList[userList.length - 1];
                userList.pop();
                break;
            }
        }

        // Clear all associated data including derived keys
        delete derivedKeys[entryId];
        delete entries[entryId];
        delete accessList[entryId];
    }

    function getEntryCount(address user) external view returns (uint256) {
        return userEntries[user].length;
    }

    function getEntryIdByIndex(address user, uint256 index) external view returns (bytes32) {
        require(index < userEntries[user].length, "Index out of bounds");
        return userEntries[user][index];
    }
}
